					count++
					spentTotal += spent
					receivedTotal += received
					balance += received - spent
					lines = append(lines, line(r.Block.Height, short(t.Txid), category(t.Coinbase, r.Block.Height),
						"spent", spent, "received", received, "net", fmt.Sprintf("%+d", received-spent),
						"balance", balance))
