type BlockRecord struct {
	Block           *Block
	Parent          *BlockRecord
	Utxo            Utxo
	TransactionFees []int
	Fees, Work      int
	Source          string
}
func newRecord(b *Block, p *BlockRecord, u Utxo, fees []int, source string) *BlockRecord {
	r := &BlockRecord{Block: b, Parent: p, Utxo: u, TransactionFees: fees, Source: source, Work: 1}
	for _, f := range fees {
		r.Fees += f
	}
	if p != nil {
		r.Work = p.Work + (1 << uint(4*b.Difficulty))
	}
	return r
}
func ancestor(r *BlockRecord, height int) *BlockRecord {
	for r.Block.Height > height {
		r = r.Parent
	}
	return r
}
func chainTo(r *BlockRecord) []*BlockRecord {
	records := []*BlockRecord{}
	for ; r != nil; r = r.Parent {
		records = append(records, r)
	}
	for i, j := 0, len(records)-1; i < j; i, j = i+1, j-1 {
		records[i], records[j] = records[j], records[i]
	}
	return records
}
func forkPoint(a, b *BlockRecord) *BlockRecord {
	h := min(a.Block.Height, b.Block.Height)
	a, b = ancestor(a, h), ancestor(b, h)
	for a != b {
		a, b = a.Parent, b.Parent
	}
	return a
}
type Block struct {
	Height                       int
	Previous, Merkle             string
	Timestamp, Difficulty, Nonce int
	Transactions                 []*Transaction
	Hash                         string
}
func newBlock(height int, previous, root string, timestamp, difficulty, nonce int, txs []*Transaction) *Block {
	return &Block{height, previous, root, timestamp, difficulty, nonce, txs, digest(headerText(height, previous, root, timestamp, difficulty, nonce))}
}
func headerText(h int, p, m string, t, d, n int) string {
	return fmt.Sprintf("%d|%s|%s|%d|%d|%d", h, p, m, t, d, n)
}
func (b *Block) Size() int {
	total := 0
	for _, t := range b.Transactions[1:] {
		total += t.Size
	}
	return total
}
func (b *Block) Txids() []string {
	ids := []string{}
	for _, t := range b.Transactions {
		ids = append(ids, t.Txid)
	}
	return ids
}
func parseBlock(fields, texts []string) *Block {
	txs := []*Transaction{}
	for _, text := range texts {
		txs = append(txs, parseTransaction(text))
	}
	return newBlock(integer(fields[3]), fields[4], fields[5], integer(fields[6]), integer(fields[7]), integer(fields[8]), txs)
}
func contextFreeError(b *Block, maxSize int) string {
	if !strings.HasPrefix(b.Hash, strings.Repeat("0", b.Difficulty)) {
		return "bad-pow"
	}
	if merkleRoot(b.Txids()) != b.Merkle {
		return "bad-merkle"
	}
	if !b.Transactions[0].Coinbase || b.Transactions[0].Height != b.Height {
		return "bad-structure"
	}
	for _, t := range b.Transactions[1:] {
		if t.Coinbase {
			return "bad-structure"
		}
	}
	if b.Size() > maxSize {
		return "too-large"
	}
	return ""
}
type Reference struct {
	Txid  string
	Index int
}
func (r Reference) String() string { return fmt.Sprintf("%s:%d", r.Txid, r.Index) }
func referenceLess(a, b Reference) bool {
	if a.Txid != b.Txid {
		return a.Txid < b.Txid
	}
	return a.Index < b.Index
}
type Output struct {
	Address string
	Amount  int
}
type Coin struct {
	Output
	Height   int
	Coinbase bool
}
type Utxo map[Reference]Coin
func (t *Transaction) OutputTotal() int {
	total := 0
	for _, out := range t.Outputs {
		total += out.Amount
	}
	return total
}
func (c Coin) Mature(height, maturity int) bool {
	return !c.Coinbase || c.Height == 0 || height >= c.Height+maturity
}
func checkTransaction(t *Transaction, utxo Utxo, spent map[Reference]bool, height, maturity int, owners map[string]*Wallet) (string, int) {
	for _, out := range t.Outputs {
		if owners[out.Address] == nil || out.Amount == 0 {
			return "bad-output", 0
		}
	}
	seen := map[Reference]bool{}
	total := 0
	for i, ref := range t.Inputs {
		if spent[ref] || seen[ref] {
			return "double-spend", 0
		}
		c, ok := utxo[ref]
		if !ok {
			return "missing-input", 0
		}
		if !c.Mature(height, maturity) {
			return "immature", 0
		}
		if t.Signatures[i] != sign(owners[c.Address].Secret, i, t.Body) {
			return "bad-sig", 0
		}
		seen[ref] = true
		total += c.Amount
	}
	if total < t.OutputTotal() {
		return "overspend", 0
	}
	return "", total - t.OutputTotal()
}
func applyTransaction(utxo Utxo, t *Transaction, height int) {
	for _, ref := range t.Inputs {
		delete(utxo, ref)
	}
	for j, out := range t.Outputs {
		utxo[Reference{t.Txid, j}] = Coin{out, height, t.Coinbase}
	}
}
func copyUtxo(source Utxo) Utxo {
	target := Utxo{}
	for k, v := range source {
		target[k] = v
	}
	return target
}
